<script setup>
import {ref,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {api} from '../lib/api';import {notice} from '../lib/state';import {date} from '../lib/format';import EditorForm from '../components/EditorForm.vue';import PageCard from '../components/PageCard.vue';
const route=useRoute(),data=ref(null),error=ref(''),saving=ref(false),upload=ref({etiqueta:'avance',sector:'',fecha:''}),files=ref([]),selected=ref(null),filter=ref('');
const base=computed(()=>`/obras/${route.params.obraId}`);
async function load(){try{data.value=await api.get(base.value+'/fotos'+(filter.value?'?etiqueta='+filter.value:''));}catch(e){error.value=e.message}}
watch(()=>[route.params.obraId,filter.value],load,{immediate:true});
async function send(){saving.value=true;error.value='';try{const form=new FormData();Object.entries(upload.value).forEach(([k,v])=>form.append(k,v||''));for(const file of files.value)form.append('fotos',file);const res=await api.post(base.value+'/fotos/subir',form);notice(`${res.created} fotografías subidas`);files.value=[];await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function edit(photo){try{selected.value=await api.get(base.value+'/registros/fotos/'+photo.id)}catch(e){error.value=e.message}}
async function save(values){saving.value=true;try{await api.put(base.value+'/registros/fotos/'+selected.value.record.id,values);selected.value=null;notice('Fotografía actualizada');await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function remove(){if(!confirm('¿Eliminar esta fotografía del registro?'))return;try{await api.del(base.value+'/registros/fotos/'+selected.value.record.id);selected.value=null;notice('Fotografía eliminada');await load()}catch(e){error.value=e.message}}
</script>
<template><div class="page-heading page-heading--module"><div class="page-heading__titles"><h2 class="page-title display">Fotografías</h2><p class="page-description">Registro visual de obras para informes semanales</p></div></div><p v-if="error" role="alert" class="notice bad">{{error}}</p><PageCard v-if="data?.editable" title="Cargar fotografías" description="Hasta 30 fotografías por carga (JPG, PNG, HEIC compatibles)"><form @submit.prevent="send"><div class="form-grid"><div class="field"><label>Imágenes</label><input type="file" accept="image/*,.heic,.heif" multiple required @change="files=Array.from($event.target.files)"/></div><div class="field"><label>Etiqueta</label><select v-model="upload.etiqueta"><option v-for="[key,label] in data.choices" :key="key" :value="key">{{label}}</option></select></div><div class="field"><label>Sector</label><input v-model="upload.sector" maxlength="80"/></div><div class="field"><label>Fecha (opcional)</label><input type="date" v-model="upload.fecha"/></div></div><div class="form-actions"><button :disabled="saving || !files.length" class="btn btn-primary">{{saving?'Subiendo…':'Subir fotografías'}}</button></div></form></PageCard>
<div class="pills record-filters"><button class="pill" :aria-current="filter===''?'page':undefined" @click="filter=''">Todas</button><button class="pill" v-for="[key,label] in data?.choices||[]" :key="key" :aria-current="filter===key?'page':undefined" @click="filter=key">{{label}}</button></div>
<div class="photo-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px"><article v-for="photo in data?.photos||[]" :key="photo.id" class="card" style="overflow:hidden"><img :src="api.file(photo.storage_path)" :alt="photo.caption||'Fotografía de obra'" style="width:100%;aspect-ratio:4/3;object-fit:cover" loading="lazy"/><div style="padding:16px"><h3 class="card__title">{{photo.sector||photo.etiqueta}}</h3><p class="muted">{{date(photo.fecha)}} · {{photo.etiqueta}}</p><p>{{photo.caption}}</p><button v-if="data?.editable" class="btn btn-sm" @click="edit(photo)">Editar</button></div></article></div>
<PageCard v-if="selected" title="Editar fotografía"><EditorForm :schema="selected.schema" :disabled="!selected.editable" :saving="saving" allow-delete @submit="save" @delete="remove"/><button class="btn" @click="selected=null">Cerrar</button></PageCard>
<p v-if="data&&!data.photos?.length" class="notice">Aún no hay fotografías en esta categoría.</p></template>
